import java.util.*;

public class Main {
    static final long mod = 1000000007;

    static class Mat {
        int rows, cols;
        long[] data;

        Mat(int r, int c) {
            this.rows = r;
            this.cols = c;
            this.data = new long[r * c];
        }

        long at(int r, int c) {
            return data[r * cols + c];
        }

        void set(int r, int c, long val) {
            data[r * cols + c] = val;
        }

        Mat add(Mat m) {
            if (rows != m.rows || cols != m.cols)
                throw new AssertionError();
            for (int i = 0; i < rows * cols; ++i)
                data[i] += m.data[i];
            return this;
        }

        Mat subtract(Mat m) {
            if (rows != m.rows || cols != m.cols)
                throw new AssertionError();
            for (int i = 0; i < rows * cols; ++i)
                data[i] -= m.data[i];
            return this;
        }

        Mat multiply(Mat m) {
            if (cols != m.rows)
                throw new AssertionError();
            Mat res = new Mat(rows, m.cols);
            for (int i = 0; i < rows; ++i) {
                for (int j = 0; j < m.cols; ++j) {
                    long sum = 0;
                    for (int k = 0; k < cols; ++k) {
                        sum += at(i, k) * m.at(k, j) % mod;
                    }
                    res.set(i, j, sum % mod);
                }
            }
            this.rows = res.rows;
            this.cols = res.cols;
            this.data = res.data;
            return this;
        }

        static Mat identity(int n) {
            Mat res = new Mat(n, n);
            for (int i = 0; i < n; ++i)
                res.set(i, i, 1);
            return res;
        }

        static Mat power(Mat a, int n) {
            assert a.rows == a.cols;
            Mat res = identity(a.rows);
            Mat base = new Mat(a.rows, a.cols);
            base.data = Arrays.copyOf(a.data, a.data.length);
            int exp = n;
            while (exp > 0) {
                if ((exp & 1) == 1)
                    res.multiply(base);
                base.multiply(base);
                exp >>= 1;
            }
            return res;
        }
    }

    static Mat[] A = new Mat[65];

    static long calc(int i, int k) {
        return Mat.power(A[i + k], k - i).multiply(Mat.power(A[i], i)).at(0, 0);
    }

    static long solve(long n, long k) {
        long cnt = 0, tmp = n;
        while (tmp != 0) {
            tmp /= k;
            cnt++;
        }
        List<Mat> b = new ArrayList<>();
        List<Mat> c = new ArrayList<>();
        List<Mat> d = new ArrayList<>();
        for (int i = 0; i <= cnt + 4; ++i) {
            b.add(new Mat(2 * (int)k + 1, 2 * (int)k + 1));
            c.add(new Mat(2 * (int)k + 1, 2 * (int)k + 1));
        }
        for (int i = 0; i <= (int)k; ++i) {
            d.add(new Mat((int)k + 1, (int)k + 1));
        }

        b.set(0, A[(int)k - 1]);
        c.set(0, Mat.power(b.get(0), (int)k - 1));
        b.set(1, new Mat(2 * (int)k + 1, 2 * (int)k + 1));
        b.get(1).data = Arrays.copyOf(b.get(0).data, b.get(0).data.length);
        c.set(1, Mat.power(b.get(1), (int)k - 1));
        Mat s = Mat.identity(2 * (int)k + 1);
        for (int j = 2; j <= cnt + 1; ++j) {
            b.set(j, new Mat(2 * (int)k + 1, 2 * (int)k + 1));
            b.get(j).data = Arrays.copyOf(b.get(j - 1).data, b.get(j - 1).data.length);
            b.set(j, calc((int)k - (j - 1) % (int)k, (int)k));
            s.multiply(c.get(j - 1));
            b.get(j).multiply(s);
            c.set(j, Mat.power(b.get(j), (int)k - 1));
        }
        int idx = 1;
        long rem = n % k;
        n -= rem;
        long q = 0;
        long tmp2 = n;
        if (tmp2 != 0) {
            while (tmp2 % k == 0) {
                ++q;
                tmp2 /= k;
            }
        }
        q = (k - q % k) % k;
        Mat ans = Mat.identity(2 * (int)k + 1);
        ans = Mat.power(A[(int)q], rem).multiply(Mat.power(A[(int)q + (int)k], Math.max(rem - q, 0)));
        n /= k;
        if (n == 0) {
            return (ans.at(2 * (int)k, 0) + ans.at(0, 0)) % mod;
        }
        --n;
        while (n != 0) {
            int t = (int) (n % k);
            if (t != 0) {
                ans.multiply(Mat.power(b.get(idx), t));
            }
            n /= k;
            ++idx;
        }
        ans.multiply(b.get(1));
        return (ans.at(2 * (int)k, 0) + ans.at(0, 0)) % mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long k = sc.nextLong();

        for (int i = 0; i <= 2 * (int)k; ++i) {
            A[i] = new Mat(2 * (int)k + 1, 2 * (int)k + 1);
            for (int j = 0; j < i; ++j)
                A[i].set(0, j, 1);
            for (int j = 0; j < 2 * (int)k - 1; ++j)
                A[i].set(j + 1, j, 1);
            A[i].set(2 * (int)k, 0, 1);
            A[i].set(2 * (int)k, 2 * (int)k, 1);
        }
        System.out.println(solve(n, k));
        sc.close();
    }
}
